def get_good_numbers():
    g = [set() for _ in range(10)]
    g[1] = set(range(1, 10))

    for k in range(2, 10):
        # To find G_k, we can try inserting a digit into each n in G_{k-1}
        for n in g[k-1]:
            s_n = str(n)
            for digit in "123456789":
                if digit in s_n:
                    continue
                # Insert digit at every possible position
                for i in range(k):
                    s_m = s_n[:i] + digit + s_n[i:]
                    m = int(s_m)
                    if m % n == 0:
                        g[k].add(m)
    return g

g_all = get_good_numbers()
max_good = 0
for k in range(1, 10):
    if g_all[k]:
        max_good = max(max_good, max(g_all[k]))

print(f"Max good: {max_good}")
for k in range(1, 10):
    print(f"G_{k} size: {len(g_all[k])}")

